107:         /// <summary>
108:         /// 保存数据
109:         /// </summary>
110:         public static void SaveEntityToDb()
111:         {
112:             while (true)
113:             {
114:                 var item = DbEntityBlockingCollection.Take();
115: 
116:                 if (item is OperateLogEntity operateLogEntity)
117:                 {
118:                     DBService.Insert(operateLogEntity);
119:                 }
120:                 else if (item is DefectStatisticsEntity defectStatisticsEntity)
121:                 {
122:                     DBService.Insert(defectStatisticsEntity);
123:                 }
124:                 else if (item is ParameterChangeLogEntity parameterChangeLogEntity)
125:                 {
126:                     Type type = parameterChangeLogEntity.GetType();
127: 
128:                     var attribute = type.GetCustomAttribute<SugarTable>();
129: 
130:                     if (attribute != null)
131:                     {
132:                         DBService.Insert(parameterChangeLogEntity);
133:                     }
134:                 }
135:                 else if (item is BondPositionLogEntity bondPositionLogEntity)
136:                 {
137:                     DBService.Insert(bondPositionLogEntity);
138:                 }
139:             }

