1404:         private void BondCompensateCalibration(int count)
1405:         {
1406:             #region 数据处理
1407: 
1408:             this.bondModule.MoveBondXYZ(this.BondCompensate.StartPoint);
1409:             this.MoveToCameraCenter(this.BondCompensate.PrName);
1410:             this.Invoke(
1411:                 new Action(
1412:                     () =>
1413:                     {
1414:                         this.SpStartNewX.EditValue = this.bondModule.BondAxisX.GetCmdPosition();
1415:                         this.SpStartNewY.EditValue = this.bondModule.BondAxisY.GetCmdPosition();
1416:                         this.SpStartNewZ.EditValue = this.bondModule.BondHead.AxisZ.GetCmdPosition();
1417:                     }));
1418: 
1419:             this.Save();
1420: 
1421:             this.result.Clear();
1422: 
1423:             #endregion
1424: 
1425:             #region 工作补偿
1426: 
1427:             for (int k = 0; k < count; k++)
1428:             {
1429:                 for (int i = 0; i < this.BondCompensate.RowCount; i++)
1430:                 {
1431:                     for (int j = 0; j < this.BondCompensate.ColumnCount; j++)
1432:                     {
1433:                         if (this.isStop)
1434:                         {
1435:                             return;
1436:                         }
1437: 
1438:                         AKRSPoint3D point3D = new AKRSPoint3D(
1439:                             this.BondCompensate.StartPoint.X
1440:                             + j * this.BondCompensate.ColumnSpacing,
1441:                             this.BondCompensate.StartPoint.Y + i * this.BondCompensate.RowSpacing,
1442:                             this.BondCompensate.StartPoint.Z);
1443: 
1444:                         AKRSPoint3D compensate = this.BondCompensate.GetBondCompensate(point3D.X, point3D.Y);
1445: 
1446:                         this.MoveXY(point3D.X + compensate.X, point3D.Y + compensate.Y);
1447: 
1448:                         Thread.Sleep(this.GlobalCalibrationDomain.Delay);
1449: 
1450:                         // 寻找Pr模板
1451:                         PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance()
1452:                             .Find(this.BondCompensate.PrName);
1453: 
1454:                         ExcuteResult re = pREntity.DoWork(this.bondModule.GetHardware(), false);
1455: 
1456:                         if (re == ExcuteResult.Success)
1457:                         {
1458:                             MatchResult matchResult = (MatchResult)pREntity.AlgResult;
1459: 
1460:                             double x = -(1224.0 - matchResult.CenterX) * (double)this.SpinX.Value * this.direct;
1461: 
1462:                             double y = (1024.0 - matchResult.CenterY) * (double)this.SpinY.Value * this.direct;
1463: 
1464:                             this.BondCompensate.BondCompensateX[i, j] += x;
1465:                             this.BondCompensate.BondCompensateY[i, j] += y;
1466: 
1467:                             this.result.Add(
1468:                                 new List<double>()
1469:                                     {
1470:                                         matchResult.CenterX,
1471:                                         matchResult.CenterY,
1472:                                         point3D.X,
1473:                                         point3D.Y,
1474:                                         x,
1475:                                         y,
1476:                                         this.BondCompensate.BondCompensateX[i, j],
1477:                                         this.BondCompensate.BondCompensateY[i, j],
1478:                                         this.bondModule.BondAxisX.GetRealPosition(),
1479:                                         this.bondModule.BondAxisY.GetRealPosition()
1480:                                     });
1481:                         }
1482:                         else
1483:                         {
1484:                             this.result.Add(
1485:                                 new List<double>()
1486:                                     {
1487:                                         99999,
1488:                                         99999,
1489:                                         99999,
1490:                                         99999,
1491:                                         99999,
1492:                                         99999,
1493:                                         99999,
1494:                                         99999
1495:                                     });
1496: 
1497:                             this.BondCompensate.BondCompensateX[i, j] += 0;
1498:                             this.BondCompensate.BondCompensateY[i, j] += 0;
1499:                         }
1500:                     }
1501:                 }
1502: 
1503:                 this.SaveBondCompensateData();
1504:             }

