137: 
138:             double interpolationY = (this.RowSpacing - offsetDistanceY) / this.RowSpacing * interpolationY1
139:                                     + offsetDistanceY / this.RowSpacing * interpolationY2;
140: 
141:             interpolationX = interpolationX / 10000.0;
142:             interpolationY = interpolationY / 10000.0;
143: 
144:             if (Math.Abs(interpolationX) > 1 || Math.Abs(interpolationY) > 1)
145:             {
146:                 throw new Exception("补偿值过大");
147:             }
148: 
149:             return (interpolationX, interpolationY);
150:         }
