152:         /// <summary>
153:         /// 获取焊头的补偿
154:         /// 相机和焊头之间有一段距离，数据都来自相机，所有焊头要减去偏移值
155:         /// </summary>
156:         /// <param name="x">点位X</param>
157:         /// <param name="y">点位Y</param>
158:         /// <param name="offset">相机和焊头之间的距离</param>
159:         /// <returns>结果</returns>
160:         public AKRSPoint3D GetBondHandCompensate(double x, double y, AKRSPoint3D offset)
161:         {
162:             // 获取相机的补偿
163:             (double, double) camera = this.GetAxisCompensate(x, y);
164: 
165:             // 获取焊头的补偿
166:             (double, double) bond = this.GetAxisCompensate(x - offset.X, y - offset.Y);
167: 
168:             // 返回差值
169:             return new AKRSPoint3D(camera.Item1 - bond.Item1, camera.Item2 - bond.Item2, 0);
